import type { Context } from './context.a';
import { Frames, header } from '../frames.ts';
import { FlowBlock } from './flow_block.a';
import { FlowEvent } from './flow_event.a';
export function syntaxFlowGraph(fileContext: Context, root: number): FlowBlock[] {
    const frames = new Frames(fileContext.bindings.rules.ask(root, 'syntax-flow-graph'));
    header(frames, 'syntax-flow-graph');
    frames.yes();
    const count = frames.natural();
    const blocks: FlowBlock[] = [];
    for(let at = 0; at < count; at++) {
        const reachable = frames.yes();
        const final = frames.yes();
        frames.yes();
        const successors = frames.ids();
        const eventCount = frames.natural();
        const flowEvents: FlowEvent[] = [];
        for(let event = 0; event < eventCount; event++) {
            const write = frames.yes();
            const kind = frames.field();
            const start = frames.natural();
            const end = frames.natural();
            flowEvents.push(new FlowEvent(fileContext.locate(kind, start, end), write));
        }
        blocks.push(new FlowBlock(reachable, final, successors, flowEvents));
    }
    frames.end();
    return blocks;
}

import { panic } from 'adamic';
import type { Bindings } from '../bindings.ts';
import { Frames, header } from '../frames.ts';
import { FlowBlock } from './flow_block.a';

export class ControlFlow {
    readonly blocks: FlowBlock[] = [];
    constructor(bindings: Bindings, root: number) {
        const frames = new Frames(bindings.rules.ask(root, 'wave07-control-flow'));
        header(frames, 'wave07-control-flow');
        const count = frames.natural();
        if(count === 0) {
            panic('empty structural control flow');
        }
        for(let at = 0; at < count; at++) {
            const reachable = frames.yes();
            const successors = frames.ids();
            if(successors.some((index) => index >= count)) {
                panic('invalid structural control-flow edge');
            }
            const events: number[] = [];
            const size = frames.natural();
            for(let event = 0; event < size; event++) {
                const kind = frames.field();
                const start = frames.natural();
                const end = frames.natural();
                events.push(
                    bindings.spans.get(`${kind}:${start}:${end}`) ?? panic('structural event absent from native tree'),
                );
            }
            this.blocks.push(new FlowBlock(reachable, successors, events));
        }
        frames.end();
    }
}

import { panic } from 'adamic';
import { Frames, header } from './frames.ts';
import type { SyntaxProjection } from './syntax_projection.a';
export class SyntaxEvent {
    readonly hook: number; readonly node: number;
    constructor(hook: number, node: number) { this.hook = hook; this.node = node; }
}
export class SyntaxBlock {
    readonly reachable: boolean; readonly successors: readonly number[]; readonly events: readonly SyntaxEvent[];
    constructor(frames: Frames) {
        this.reachable = frames.yes(); this.successors = frames.ids(); const count = frames.natural(); const events: SyntaxEvent[] = [];
        for(let at = 0; at < count; at++) { events.push(new SyntaxEvent(frames.natural(), frames.natural())); } this.events = events;
    }
}
export class SyntaxControlFlow {
    readonly blocks: readonly SyntaxBlock[];
    constructor(syntax: SyntaxProjection, root: number) {
        const frames = new Frames(syntax.ask(root, 'syntax-control-flow')); header(frames, 'syntax-control-flow'); const count = frames.natural(); const blocks: SyntaxBlock[] = [];
        for(let at = 0; at < count; at++) { blocks.push(new SyntaxBlock(frames)); } frames.end(); this.blocks = blocks;
        if(count === 0) { panic('empty control flow graph'); }
        for(const block of blocks) {
            for(const next of block.successors) { if(next >= count) { panic('invalid control flow successor'); } }
            for(const event of block.events) { if(event.hook > 1) { panic('invalid syntax hook'); } syntax.node(event.node); }
        }
    }
    block(index: number): SyntaxBlock { return this.blocks[index] ?? panic('missing control flow block'); }
}
